package com.aistock.scheduler.alert;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import java.net.*;import java.util.concurrent.atomic.AtomicReference;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.HttpServer;import org.junit.jupiter.api.Test;
class AlertMarketClientTest {
 final Instant now=Instant.parse("2026-10-10T08:00:00Z");final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 @Test void calendarAndRefreshUseExactContractAndToken()throws Exception{var path=new AtomicReference<String>();var body=new AtomicReference<JsonNode>();var c=AlertCalendarPlanTest.calendar(now);var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",ex->{assertEquals("private",ex.getRequestHeaders().getFirst("X-Service-Token"));path.set(ex.getRequestURI().toString());byte[] input=ex.getRequestBody().readAllBytes();body.set(input.length==0?null:mapper.readTree(input));var d=mapper.createObjectNode().put("versionId",c.versionId().toString());d.set("candidate",mapper.valueToTree(Map.of("provider",c.provider(),"start",c.start(),"end",c.end(),"fetchedAt",c.fetchedAt(),"sourcePayloadHash",c.sourcePayloadHash(),"days",c.days())));var n=mapper.createObjectNode().put("code","OK");n.set("data",d);var out=mapper.writeValueAsBytes(n);ex.sendResponseHeaders(200,out.length);ex.getResponseBody().write(out);ex.close();});server.start();try{String base="http://127.0.0.1:"+server.getAddress().getPort();var client=new HttpAlertMarketClient(base,base,"private",mapper,Clock.fixed(now,ZoneOffset.UTC));assertEquals(c.versionId(),client.calendar().versionId());assertEquals("/internal/v1/market/calendar?start=2025-10-09&end=2026-10-10",path.get());var op=UUID.randomUUID();client.refresh(op,c.start(),c.end());assertEquals("/internal/v1/market/calendar/refresh",path.get());assertEquals(3,body.get().size());assertEquals(op.toString(),body.get().path("operationId").asText());assertEquals(c.start().toString(),body.get().path("start").asText());}finally{server.stop(0);}}
 @Test void boundaryAndDueValidateIdentityTypesAndCursor()throws Exception{for(String mode:List.of("valid","wrong-stock","revision-text","bad-cursor","future","wrong-provider")){var raw=UUID.randomUUID();var rule=UUID.randomUUID();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",ex->{var n=mapper.createObjectNode().put("code","OK");var d=n.putObject("data");if(ex.getRequestURI().getPath().contains("alert-boundary")){d.put("instrumentId",mode.equals("wrong-stock")?"SZ000002":"SH600030").put("provider",mode.equals("wrong-provider")?"unknown":"baostock").put("rawVersionId",raw.toString()).put("latestPublishedTradeDate","2026-10-09").put("expectedCompletedTradeDate","2026-10-09").put("effectiveAfterTradeDate",mode.equals("future")?"2026-10-11":"2026-10-09").put("calendarHash","a".repeat(64)).put("asOf",now.toString()).put("definition","alert-boundary-v1");}else{assertTrue(ex.getRequestURI().getQuery().contains("limit=50"));d.putNull("nextCursor");if(mode.equals("bad-cursor"))d.put("nextCursor",UUID.randomUUID().toString());var item=d.putArray("items").addObject().put("ruleId",rule.toString()).put("ownerId",UUID.randomUUID().toString()).put("instrumentId",mode.equals("wrong-stock")?"SZ000002":"SH600030").put("revision",0).put("effectiveAfterTradeDate",mode.equals("future")?"2026-10-11":"2026-10-08");if(mode.equals("revision-text"))item.put("revision","0");}var out=mapper.writeValueAsBytes(n);ex.sendResponseHeaders(200,out.length);ex.getResponseBody().write(out);ex.close();});server.start();try{String base="http://127.0.0.1:"+server.getAddress().getPort();var client=new HttpAlertMarketClient(base,base,"private",mapper,Clock.fixed(now,ZoneOffset.UTC));if(Set.of("wrong-stock","future","wrong-provider").contains(mode))assertThrows(RuntimeException.class,()->client.boundary("SH600030"));else assertEquals(raw,client.boundary("SH600030").rawVersionId());if(Set.of("wrong-stock","revision-text","bad-cursor","future").contains(mode))assertThrows(RuntimeException.class,()->client.due("SH600030",null,50));else assertEquals(rule,client.due("SH600030",null,50).items().get(0).ruleId());}finally{server.stop(0);}}}
 @Test void invalidCalendarFieldTypesCannotBeCoerced()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",ex->{var c=AlertCalendarPlanTest.calendar(now);var n=mapper.createObjectNode().put("code","OK");var d=n.putObject("data").put("versionId",c.versionId().toString());var candidate=d.putObject("candidate").put("provider","baostock").put("start",c.start().toString()).put("end",c.end().toString()).put("fetchedAt",now.toString()).put("sourcePayloadHash",c.sourcePayloadHash());candidate.putArray("days").addObject().put("date",c.start().toString()).put("open","true");var out=mapper.writeValueAsBytes(n);ex.sendResponseHeaders(200,out.length);ex.getResponseBody().write(out);ex.close();});server.start();try{String base="http://127.0.0.1:"+server.getAddress().getPort();assertThrows(RuntimeException.class,()->new HttpAlertMarketClient(base,base,"private",mapper,Clock.fixed(now,ZoneOffset.UTC)).calendar());}finally{server.stop(0);}}
}
